SELECT "t8"."order_number", "t8"."line_no", "t8"."item", "t8"."unit_price", "t8"."list_price", 'hold_sales' AS "route", 'price_differences' AS "context"
FROM (SELECT "order_number0" AS "order_number", "line_no0" AS "line_no", "item", "unit_price", "price" AS "list_price"
        FROM (SELECT "t1"."order_number", "t1"."line_no", "t1"."item", "t1"."unit_price", "t1"."customer", "t1"."channel", "t1"."placed_date", "t5"."order_number" AS "order_number0", "t5"."line_no" AS "line_no0", "t5"."price"
                FROM (SELECT "sales_line"."order_number", "sales_line"."line_no", "sales_line"."item", "sales_line"."unit_price", "t0"."customer", "t0"."channel", "t0"."placed_date"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    INNER JOIN (SELECT "t4"."order_number", "t4"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t3"."customer", "t3"."channel", "t3"."placed_date"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t3"
                                    INNER JOIN "sales_line" AS "sales_line0" ON "t3"."order_number" = "sales_line0"."order_number") AS "t4"
                            LEFT JOIN "customer_price" ON "t4"."item" = "customer_price"."item" AND "t4"."customer" = "customer_price"."customer" AND "t4"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t4"."placed_date" <= "customer_price"."valid_to")
                            LEFT JOIN "price_list" ON "t4"."item" = "price_list"."item" AND "t4"."channel" = "price_list"."channel" AND "t4"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t4"."placed_date" <= "price_list"."valid_to")) AS "t5" ON "t1"."order_number" = "t5"."order_number" AND "t1"."line_no" = "t5"."line_no") AS "t6"
        WHERE "t6"."price" IS NULL OR ABS("t6"."unit_price" - "t6"."price") > :tolerance) AS "t8"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t39"."order_number", "t39"."customer", "t39"."channel", "t39"."fulfilling_warehouse", "t39"."value", "t39"."placed_date", "t39"."state", COALESCE("t39"."n_short", 0) AS "n_short", COALESCE("t39"."n_price", 0) AS "n_price", COALESCE("t45"."n_due", 0) AS "n_due"
                FROM (SELECT "t27"."order_number", "t27"."customer", "t27"."channel", "t27"."fulfilling_warehouse", "t27"."value", "t27"."placed_date", "t27"."state", "t27"."n_short", "t38"."n_price"
                        FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t26"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t10"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t21"."order_number", "t21"."customer", "t21"."channel", "t21"."fulfilling_warehouse", "t21"."value", "t21"."placed_date", "t21"."state", "t21"."line_no", "t21"."item", "t21"."quantity", "t21"."unit_price", "t21"."ext_sales_price", "t21"."warehouse", "t21"."sold_date", "t21"."customer0", "t21"."channel0", "t21"."as_of_date", "t21"."quantity_on_hand", "t21"."_ttrp_g_n9_0", "t21"."_ttrp_g_n9_1", "t21"."_ttrp_latest_n9", "t22"."warehouse" AS "warehouse0", "t22"."from_date", "t22"."to_date", "t22"."reason", COALESCE("t21"."quantity_on_hand", 0) AS "on_hand", "t22"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT *
                                                        FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "t14"."line_no", "t14"."item", "t14"."quantity", "t14"."unit_price", "t14"."ext_sales_price", "t14"."warehouse", "t14"."sold_date", "t14"."customer0", "t14"."channel0", "t14"."as_of_date", "t14"."quantity_on_hand", "t14"."_ttrp_g_n9_0", "t14"."_ttrp_g_n9_1", "t19"."_ttrp_latest_n9"
                                                                FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t13"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t13"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t13"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t13"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                        FROM "order"
                                                                                        WHERE "state" IN ('held', 'placed')) AS "t12"
                                                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t12"."order_number" = "sales_line1"."order_number") AS "t13"
                                                                            LEFT JOIN "inventory" ON "t13"."item" = "inventory"."item" AND "t13"."warehouse" = "inventory"."warehouse") AS "t14"
                                                                    INNER JOIN (SELECT CASE WHEN "t17"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t17"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                                                        FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."quantity", "sales_line2"."unit_price", "sales_line2"."ext_sales_price", "sales_line2"."warehouse", "sales_line2"."sold_date", "sales_line2"."customer" AS "customer0", "sales_line2"."channel" AS "channel0"
                                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                        FROM "order"
                                                                                        WHERE "state" IN ('held', 'placed')) AS "t16"
                                                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t16"."order_number" = "sales_line2"."order_number") AS "t17"
                                                                            LEFT JOIN "inventory" AS "inventory0" ON "t17"."item" = "inventory0"."item" AND "t17"."warehouse" = "inventory0"."warehouse"
                                                                        GROUP BY CASE WHEN "t17"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."order_number" AS VARCHAR) END, CASE WHEN "t17"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."line_no" AS VARCHAR) END) AS "t19" ON "t14"."_ttrp_g_n9_0" = "t19"."_ttrp_g_n9_0" AND "t14"."_ttrp_g_n9_1" = "t19"."_ttrp_g_n9_1") AS "t20"
                                                        WHERE "t20"."as_of_date" = "t20"."_ttrp_latest_n9" OR "t20"."_ttrp_latest_n9" IS NULL) AS "t21"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t22" ON "t21"."warehouse" = "t22"."warehouse") AS "t23"
                                        WHERE "t23"."outage" OR "t23"."on_hand" < "t23"."quantity"
                                        GROUP BY "order_number") AS "t26" ON "t10"."order_number" = "t26"."order_number") AS "t27"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t30"."order_number", "t30"."line_no", "t30"."item", "t30"."unit_price", "t30"."customer", "t30"."channel", "t30"."placed_date", "t34"."order_number" AS "order_number0", "t34"."line_no" AS "line_no0", "t34"."price"
                                        FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t29"."customer", "t29"."channel", "t29"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t29"
                                                    INNER JOIN "sales_line" AS "sales_line3" ON "t29"."order_number" = "sales_line3"."order_number") AS "t30"
                                            INNER JOIN (SELECT "t33"."order_number", "t33"."line_no", COALESCE("customer_price0"."price", "price_list0"."price") AS "price"
                                                FROM (SELECT "sales_line4"."order_number", "sales_line4"."line_no", "sales_line4"."item", "sales_line4"."unit_price", "t32"."customer", "t32"."channel", "t32"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t32"
                                                            INNER JOIN "sales_line" AS "sales_line4" ON "t32"."order_number" = "sales_line4"."order_number") AS "t33"
                                                    LEFT JOIN "customer_price" AS "customer_price0" ON "t33"."item" = "customer_price0"."item" AND "t33"."customer" = "customer_price0"."customer" AND "t33"."placed_date" >= "customer_price0"."valid_from" AND ("customer_price0"."valid_to" IS NULL OR "t33"."placed_date" <= "customer_price0"."valid_to")
                                                    LEFT JOIN "price_list" AS "price_list0" ON "t33"."item" = "price_list0"."item" AND "t33"."channel" = "price_list0"."channel" AND "t33"."placed_date" >= "price_list0"."valid_from" AND ("price_list0"."valid_to" IS NULL OR "t33"."placed_date" <= "price_list0"."valid_to")) AS "t34" ON "t30"."order_number" = "t34"."order_number" AND "t30"."line_no" = "t34"."line_no") AS "t35"
                                WHERE "t35"."price" IS NULL OR ABS("t35"."unit_price" - "t35"."price") > :tolerance
                                GROUP BY "order_number0") AS "t38" ON "t27"."order_number" = "t38"."order_number") AS "t39"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t41"."order_number", "t41"."customer", "t41"."channel", "t41"."fulfilling_warehouse", "t41"."value", "t41"."placed_date", "t41"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t41"
                                    INNER JOIN "invoice" ON "t41"."customer" = "invoice"."customer") AS "t42"
                        WHERE "t42"."status" = 'open' AND "t42"."due" < :as_of
                        GROUP BY "order_number") AS "t45" ON "t39"."order_number" = "t45"."order_number") AS "t46"
        WHERE "t46"."n_short" > 0 OR "t46"."n_price" > 0
        GROUP BY "order_number") AS "t49" ON "t8"."order_number" = "t49"."order_number"
